/* Build a file:// compatible bundle from the single authored DTCG document. */
const fs = require('node:fs');
const path = require('node:path');
const Tokens = require('../themes/tokens/tokens.js');
const directory = path.resolve(__dirname, '../themes/tokens');
const document = JSON.parse(fs.readFileSync(path.join(directory, 'palette.tokens.json'), 'utf8'));
Tokens.validate(document);
fs.writeFileSync(path.join(directory, 'defaults.js'),
  '/* Generated by ui/scripts/build-defaults.cjs. Edit palette.tokens.json, not this file. */\n' +
  '(function(root){const tokens=' + JSON.stringify(document) +
  ';if(typeof module===\'object\'&&module.exports)module.exports=tokens;else root.DesignSystemDefaultTokens=tokens;})(globalThis);\n');
